#!/usr/bin/env python3

import os

def find_broken_symlinks(root_dir):
    """Find all broken symbolic links in the given directory and subdirectories."""
    broken_links = []

    for dirpath, dirnames, filenames in os.walk(root_dir):
        # Check for broken symlinks in directories
        for dirname in dirnames:
            full_path = os.path.join(dirpath, dirname)
            if os.path.islink(full_path) and not os.path.exists(full_path):
                broken_links.append(os.path.abspath(full_path))

        # Check for broken symlinks in files
        for filename in filenames:
            full_path = os.path.join(dirpath, filename)
            if os.path.islink(full_path) and not os.path.exists(full_path):
                broken_links.append(os.path.abspath(full_path))

    return broken_links

if __name__ == "__main__":
    root_directory = "/tmp/mcp-workspace"
    broken_links = find_broken_symlinks(root_directory)

    # Write to output file
    output_file = "/tmp/mcp-workspace/broken_links.txt"
    with open(output_file, "w") as f:
        for link in broken_links:
            f.write(link + "\n")

    print(f"Found {len(broken_links)} broken symbolic links.")
    if broken_links:
        print("Broken links:")
        for link in broken_links:
            print(f"  {link}")
    else:
        print("No broken symbolic links found.")

